195	func printTrailDetails(w io.Writer, m *trail.Metadata, webURL, bodyText string) {
196		fmt.Fprintf(w, "Trail: %s\n", m.Title)
197		if m.Number > 0 {
198			fmt.Fprintf(w, "  Number:  %d\n", m.Number)
199		}
200		if !m.TrailID.IsEmpty() {
201			fmt.Fprintf(w, "  ID:      %s\n", m.TrailID)
202		}
203		fmt.Fprintf(w, "  Branch:  %s\n", m.Branch)
204		fmt.Fprintf(w, "  Base:    %s\n", m.Base)
205		fmt.Fprintf(w, "  Status:  %s\n", m.Status)
206		fmt.Fprintf(w, "  Author:  %s\n", m.AuthorLogin())
207		if strings.TrimSpace(m.Phase) != "" {
208			fmt.Fprintf(w, "  Phase:   %s\n", trailPhaseDisplay(m.Phase))
209		}
210		if webURL != "" {
211			fmt.Fprintf(w, "  URL:     %s\n", webURL)
212		}
213		if len(m.Labels) > 0 {
214			fmt.Fprintf(w, "  Labels:  %s\n", strings.Join(m.Labels, ", "))
215		}
216		if len(m.Assignees) > 0 {
217			fmt.Fprintf(w, "  Assignees: %s\n", strings.Join(m.Assignees, ", "))
218		}
219		fmt.Fprintf(w, "  Created: %s\n", m.CreatedAt.Format("2006-01-02T15:04:05Z07:00"))
220		fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
221		if strings.TrimSpace(bodyText) != "" {
222			fmt.Fprintf(w, "\nDescription:\n%s\n", bodyText)
223		}
