226	// noTrailDescription is shown by `trail show` when a trail's description loaded
227	// successfully but is empty — distinguishing "no description yet" from a load
228	// failure (which warns and renders nothing).
229	const noTrailDescription = "-- no description provided --"
230	
231	// trailDescriptionForDisplay returns the text `trail show` renders for the
232	// description: the body when present; the placeholder when it loaded but is
233	// empty; or "" when it couldn't be loaded (the caller has already warned).
234	func trailDescriptionForDisplay(bodyText string, loaded bool) string {
235		if strings.TrimSpace(bodyText) != "" {
236			return bodyText
237		}
238		if loaded {
239			return noTrailDescription
240		}
241		return ""
242	}
243	
244	// trailWebURL builds the browser URL for a trail:
245	// <web-origin>/<forge>/<owner>/<repo>/trails/<number>. In production the web app
246	// is served from the same origin as the data API, so the API base URL doubles
247	// as the web origin. A split local-dev setup (API and frontend on different
248	// ports) would point this at the API port rather than the dev frontend.
249	func trailWebURL(base, forge, owner, repo string, number int) string {
250		return strings.TrimRight(base, "/") + "/" + forge + "/" + owner + "/" + repo + "/trails/" + strconv.Itoa(number)
251	}
252	
253	// fetchTrailDescription fetches a trail's rendered description text
254	// (`trail.body_document.text_snapshot`), which the list endpoint omits, by
255	// integer number. It returns only the description — the list result already
256	// supplies the metadata — and decodes only the fields it needs, so it is
257	// unaffected by the shape of sibling fields like `checkpoints`/`thread`.
258	func fetchTrailDescription(ctx context.Context, client *api.Client, forge, owner, repo string, number int) (string, error) {
259		resp, err := client.Get(ctx, trailNumberPath(forge, owner, repo, number))
260		if err != nil {
261			return "", fmt.Errorf("failed to fetch trail detail: %w", err)
262		}
263		defer resp.Body.Close()
264		if err := checkTrailResponse(resp); err != nil {
265			return "", err
266		}
267		var detail struct {
268			Trail api.TrailResource `json:"trail"`
269		}
270		if err := api.DecodeJSON(resp, &detail); err != nil {
271			return "", fmt.Errorf("failed to decode trail detail: %w", err)
272		}
273		if detail.Trail.BodyDocument == nil {
274			return "", nil
275		}
276		return strings.TrimSpace(detail.Trail.BodyDocument.TextSnapshot), nil
277	}
