async function resolveRepoContext(c: TrailContext): Promise<ResolvedRepoContext | Response> {
  const userId = c.get("userId") as string
  const host = c.req.param("host") ?? ""
  const owner = c.req.param("owner") ?? ""
  const repo = c.req.param("repo") ?? ""

  if (!VALID_HOSTS.includes(host)) {
    return c.json({ error: `Invalid host. Must be one of: ${VALID_HOSTS.join(", ")}` }, 400)
  }

  const repoSlug = `${host}/${owner}/${repo}`
  const repoFullName = `${owner}/${repo}`
  const db = getDb(c.env)

  const result = await db.repos.getByFullNameWithAccess(repoFullName, userId)
  let repoRecord: Repo | null = null
  let hasMembership = false

  if (result.status === "found") {
    repoRecord = result.repo
    hasMembership = true
  } else if (result.status === "no_access") {
    repoRecord = await db.repos.getPublicByFullName(repoFullName)
  }

  if (!repoRecord || !repoRecord.trails_enabled) {
    return c.json({ error: "Repository not found" }, 404)
  }

  return { db, userId, repo: repoRecord, repoFullName, repoSlug, hasMembership }
}

async function resolveTrailContext(c: TrailContext): Promise<ResolvedTrailContext | Response> {
  const base = await resolveRepoContext(c)
  if (base instanceof Response) return base

  const raw = c.req.param("number") ?? ""
  const trailNumber = parseTrailNumber(raw)
  if (trailNumber === null) {
    return c.json({ error: "Invalid trail number format" }, 400)
  }

  const trail = await base.db.trails.getByNumber(base.repo.id, trailNumber)
  if (!trail) {
    return c.json({ error: "Trail not found" }, 404)
  }

  return { ...base, trail }
}

