import { describe, expect, it } from "vitest"

import { buildTrailUrl } from "./trail-pr-shared"

describe("buildTrailUrl", () => {
  it("builds a url from host + repo full name", () => {
    expect(buildTrailUrl("https://entire.io", "gh", "org/repo", 42)).toBe(
      "https://entire.io/gh/org/repo/trails/42",
    )
  })

  it("strips a trailing slash on the base url", () => {
    expect(buildTrailUrl("https://entire.io/", "gh", "org/repo", 42)).toBe(
      "https://entire.io/gh/org/repo/trails/42",
    )
  })

  it("url-encodes the host and repo segments", () => {
    expect(buildTrailUrl("https://entire.io", "et", "my org/weird repo", 7)).toBe(
      "https://entire.io/et/my%20org/weird%20repo/trails/7",
    )
  })
})

